INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29701, 'Revelation 8:6', 'Revelation', 8, 6, '&nbsp;بيا هغه اووۀ فرښتې چې ورسره اووۀ بيګلونه وُو، غږولو ته تيارې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29702, 'Revelation 8:7', 'Revelation', 8, 7, '&nbsp;وړومبۍ فرښتې خپل بيګل وغږولو نو اور او ږلۍ د وينې سره په زمکه راوورېدل او د زمکې درېمه حِصه وسوزېدله او د ونو درېمه حِصه وسوزېدله او ټول شنۀ واښۀ وسوزېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29703, 'Revelation 8:8', 'Revelation', 8, 8, '&nbsp;بيا کله چې دوېمې فرښتې خپل بيګل وغږولو نو لکه يو لوئ غر چې اور پرې بل وى، سمندر ته وغورزولے شو او د سمندر درېمه حِصه وينه شوه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29704, 'Revelation 8:9', 'Revelation', 8, 9, '&nbsp;او په دې باندې د سمندر درېمه حِصه ژوندى مخلوقات مړۀ شول او د سمندرى جهازونو دريمه حِصه په اوبو کښې ډوب شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29705, 'Revelation 8:10', 'Revelation', 8, 10, '&nbsp;نو بيا درېمې فرښتې خپل بيګل وغږولو نو يو لوئ ستورے له آسمان نه راوغورزېدو چې د مشعل په شان بلېدو او دا د سيندونو او چينو په درېمه حِصه ورپرېوتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29706, 'Revelation 8:11', 'Revelation', 8, 11, '&nbsp;د ستورى نوم ګنډير وو. او د اوبو درېمه حِصه د ګنډير په شان ترخه شوه او ډېر زيات خلق د دې ترخو اوبو څښلو په وجه مړۀ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29707, 'Revelation 8:12', 'Revelation', 8, 12, '&nbsp;بيا څلورمې فرښتې خپل بيګل وغږولو نو دې سره د نمر درېمه حِصه او د سپوږمۍ او د ستورو درېمه حِصه ووهلے شوه نو د دوئ درېمه حِصه تيارۀ شوله او د ورځې درېمه حِصه رڼا ختمه شوه او دغه شان د شپې دريمه حِصه رڼا هم ختمه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29708, 'Revelation 8:13', 'Revelation', 8, 13, '&nbsp;بيا ما وليدل چې يو باز په آسمان کښې بره والوتو او په اوچت آواز يې دا نعرې وهلې چې، ”افسوس، افسوس، افسوس، د زمکې په اوسېدونکو باندې، ځکه چې هغه درې نورې پاتې فرښتې به هم اوس خپل بيګل غږوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29709, 'Revelation 9:1', 'Revelation', 9, 1, '&nbsp;بيا پينځمې فرښتې خپل بيګل وغږولو او ما يو ستورے وليدو چې د آسمان نه زمکې ته راپرېوتے وو او هغه ستورى ته د عالمِ ارواح چابيانې ورکړے شوې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29710, 'Revelation 9:2', 'Revelation', 9, 2, '&nbsp;کله چې هغۀ عالمِ ارواح کولاو کړه نو د هغه لوئې کندې نه د بټۍ په شان لوګے راوختلو او د عالمِ ارواح لوګى نمر او باد تور کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29711, 'Revelation 9:3', 'Revelation', 9, 3, '&nbsp;بيا د لوګى نه په زمکه مُلخان راغلل او هغوئ د زمکې د لړمانو په شان د چيچلو اختيار ورکړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29712, 'Revelation 9:4', 'Revelation', 9, 4, '&nbsp;هغوئ ته دا حُکم ورکړے شوے وو چې واښو، ونو، او بوټو ته هيڅ نقصان ونۀ رسوئ خو بس هغه کسانو ته ټک ورکړئ د چا په تندى چې د خُدائ پاک مهر نۀ وى لګېدلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29713, 'Revelation 9:5', 'Revelation', 9, 5, '&nbsp;هغوئ ته اجازت ورکړے شوے وو چې د پينځو مياشتو پورې هغوئ ته عذاب ورکړئ، خو دا نه چې هغوئ مړۀ کړئ او د هغوئ عذاب لکه د لړم د ټک په شان وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29714, 'Revelation 9:6', 'Revelation', 9, 6, '&nbsp;په دې ورځو کښې به خلق مرګ غواړى خو مرګ به ورته نۀ ملاويږى، هغوئ به د مرګ خواهش کوى خو مرګ به د هغوئ نه تښتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29715, 'Revelation 9:7', 'Revelation', 9, 7, '&nbsp;دا مُلخان لکه د جنګى آسونو په شان وُو او د هغوئ په سرونو تاجُونه لکه د سرو زرو په شان وُو او د هغوئ مخونه د انسان په شان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29716, 'Revelation 9:8', 'Revelation', 9, 8, '&nbsp;او د هغوئ وېښتۀ د ښځو د وېښتو په شان وو او د هغوئ غاښونه د زمرو د غاښونو په شان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29717, 'Revelation 9:9', 'Revelation', 9, 9, '&nbsp;د هغوئ زغرې لکه د اوسپنو د زغرو په شان وې او د هغوئ د وزرونو آوازونه لکه د ډېرو جنګى ګاډو د آسونو په شان وُو کوم چې حمله کوونکى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29718, 'Revelation 9:10', 'Revelation', 9, 10, '&nbsp;د هغوئ په لکو کښې د لړمانو په شان لشې وې او د هغوئ ټک ورکولو به انسانان تر پينځو مياشتو پورې عذابول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29719, 'Revelation 9:11', 'Revelation', 9, 11, '&nbsp;او د هغوئ بادشاه د عالمِ ارواح فرښته وه چې په عبرانۍ کښې د هغې نوم ابدون، او په يونانۍ ژبه کښې اپوليون، يعنې تباه کوونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29720, 'Revelation 9:12', 'Revelation', 9, 12, '&nbsp;اولنے افسوس تېر شو خو دوه نور لا راتلونکى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29721, 'Revelation 9:13', 'Revelation', 9, 13, '&nbsp;بيا هغه شپږمې فرښتې خپل بيګل وغږولو او ما يو آواز واورېدو چې د خُدائ پاک په وړاندې ولاړ د سرو زرو د قربان‌ګاه د څلورو ښکرونو د مينځ نه راووتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29722, 'Revelation 9:14', 'Revelation', 9, 14, '&nbsp;هغۀ شپږمې فرښتې ته ووئيل چا سره چې بيګل وو چې، ”د لوئ فرات د سيند په غاړه تړلې څلور فرښتې آزادې کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29723, 'Revelation 9:15', 'Revelation', 9, 15, '&nbsp;نو هغه څلور فرښتې آزادې کړے شوې څوک چې د درېمې برخې بنى آدمو د وژلو دپاره د دې کال، د دې مياشتې، د دې ورځې او د دې ساعت دپاره مقرر شوې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29724, 'Revelation 9:16', 'Revelation', 9, 16, '&nbsp;نو ما ته ووئيلے شول چې په آسونو د سوارو فوجيانو شمېر شل کروړه وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29725, 'Revelation 9:17', 'Revelation', 9, 17, '&nbsp;او دغسې ما هغه آسونه او د هغوئ سوارۀ په خپله رويا کښې وليدل، هغوئ د اور په شان ځلېدونکى سرې، آسمانى رنګې او د ګوګړو په شان زېړې زغرې اغوستې وې. او د آسونو سرونه يې د زمرو د سرونو په شان وُو او د هغوئ خولې نه اور، لوګے او ګوګړ راوتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29726, 'Revelation 9:18', 'Revelation', 9, 18, '&nbsp;په دې درې افتونو د دُنيا دريمه حِصه خلق مړۀ شول يعنې په اور، لوګى او ګوګړو کوم چې د هغوئ د خولې نه راوتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29727, 'Revelation 9:19', 'Revelation', 9, 19, '&nbsp;د آسونو طاقت د هغوئ په خولو او لکو کښې وو. نو د هغوئ د لکو لکه د مارانو په شان سرونه وُو او د انسانانو د زخمى کولو طاقت ورسره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29728, 'Revelation 9:20', 'Revelation', 9, 20, '&nbsp;خو دې افتونو کښې چې کوم انسانان ژوندى پاتې شول هغوئ د خپلو بدو عملونو نه توبه ونۀ ويستله. او هغوئ د پيريانو او د سرو زرو، سپينو زرو، زېړو، کاڼو او د لرګو نه د جوړو شوو بُتانو عبادت کول پرې نۀ ښودل، کوم بُتان چې نۀ ليدلے او نۀ اورېدلے او نۀ ګرځېدلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29729, 'Revelation 9:21', 'Revelation', 9, 21, '&nbsp;او نۀ هغوئ د خپلو قتلونو، جادوګرۍ، حرامکارۍ، او نۀ يې د خپلو غلاګانو نه توبه وويستله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29730, 'Revelation 10:1', 'Revelation', 10, 1, '&nbsp;بيا ما يوه بله طاقتوره فرښته د آسمان نه په راکوزېدو وليده چې په وريځ کښې پټه وه او چې د بوډۍ ټال يې په سر وو، مخ يې د نمر په شان ځلېدو او پښې يې د اور د ستنو په شان وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29731, 'Revelation 10:2', 'Revelation', 10, 2, '&nbsp;او د هغې په لاس کښې يو ورکوټے پرانستلے شوے طومار وو. هغې ښۍ پښه په سمندر کښې کېښوده او ګسه پښه يې په زمکه اېښې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29732, 'Revelation 10:3', 'Revelation', 10, 3, '&nbsp;بيا هغې د ازمرى د غړمبار په شان يوه لويه چغه وويستله او کله چې هغې چغه کړه نو اووۀ تندرونه وګړزېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29733, 'Revelation 10:4', 'Revelation', 10, 4, '&nbsp;او کله چې اوو واړه تندرونه وګړزېدل، نو ما دا ليکل نو بيا ما د آسمان نه يو آواز واورېدو چې وئيل يې، ”دا پټ وساته څۀ چې اوو واړه تندرونو ووئيل، او دا مۀ ليکه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29734, 'Revelation 10:5', 'Revelation', 10, 5, '&nbsp;بيا هغه فرښته کومه چې ما په سمندر او په زمکه ولاړه ليدلې وه هغې خپل ښے لاس آسمان طرف ته اوچت کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29735, 'Revelation 10:6', 'Revelation', 10, 6, '&nbsp;او قسم يې په هغه چا وخوړلو څوک چې تل تر تله ژوندے دے چا چې په آسمان، زمکه، سمندر او هر څۀ چې په دوئ کښې دى پېدا کړى دى. هغۀ ووئيل چې، ”نور انتظار کول به نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29736, 'Revelation 10:7', 'Revelation', 10, 7, '&nbsp;په هغه ورځو چې کله اوومه فرښته خپل بيګل وغږوى نو د خُدائ پاک پټ رازونه به پوره شى څنګه چې هغۀ خپلو خادِمانو نبيانو ته فرمائيلى وُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29737, 'Revelation 10:8', 'Revelation', 10, 8, '&nbsp;هغه آواز چې ما د آسمان نه اورېدلے وو، بيا ما سره په خبرو شو او وې فرمائيل چې، ”لاړ شه او په سمندر او په زمکه ولاړې فرښتې د لاس نه هغه پرانستلے شوے طومار واخله.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29738, 'Revelation 10:9', 'Revelation', 10, 9, '&nbsp;نو زۀ هغې فرښتې له لاړم او ورته مې ووئيل چې، ”ما ته هغه پرانستلے شوے ورکوټے طومار راکړه.“ نو هغې ما ته ووئيل چې، ”دا واخله او وې خوره، دا به ستا خېټه ترخه کړى خو ستا په خولۀ کښې به لکه د شاتو خوږ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29739, 'Revelation 10:10', 'Revelation', 10, 10, '&nbsp;نو ما هغه ورکوټے طومار د فرښتې د لاس نه واخستو او ومې خوړلو. دا زما په خولۀ لکه د شاتو خوږ ولګېدو خو چې مې تېر کړو نو زما خېټه يې ترخه کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29740, 'Revelation 10:11', 'Revelation', 10, 11, '&nbsp;بيا ما ته ووئيلے شُو چې، ”دا ضرورى دى چې تۀ د ډېرو خلقو او قومونو او ژبو او بادشاهانو په حقله پېشګوئې وکړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29741, 'Revelation 11:1', 'Revelation', 11, 1, '&nbsp;ما ته د ناپ کولو د ګز په شان يوه لښته راکړے شوه او راته ووئيلے شو چې، ”اوس پاڅه او د خُدائ پاک کور او قربان‌ګاه کچ کړه او عبادت کوونکى شمار کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29742, 'Revelation 11:2', 'Revelation', 11, 2, '&nbsp;خو د خُدائ د کور بهر دربار مۀ کچ کوه ځکه چې دا غېرو قومونو ته ورکړے شوے دے او هغوئ به دا مقدس ښار تر دوو څلوېښتو مياشتو پورې د پښو لاندې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29743, 'Revelation 11:3', 'Revelation', 11, 3, '&nbsp;او زۀ به خپل دوه ګواهان د ټاټ جامې اغوستې د پېشګويۍ دپاره مقرر کړم او دوئ به تر دولس سوه شپېتو ورځو پورې نبوت کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29744, 'Revelation 11:4', 'Revelation', 11, 4, '&nbsp;دا هغه دوه د زيتون ونې او دوه ډيوټونه دى کوم چې د زمکې د مالِک د وړاندې ولاړ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29745, 'Revelation 11:5', 'Revelation', 11, 5, '&nbsp;کۀ څوک دوئ ته نقصان رسول غواړى نو د دوئ د خولې نه اور راوځى او د دوئ دشمنان به وسوزوى او دغه شان به هر هغه څوک چې دوئ ته نقصان رسول غواړى، نو هغوئ به په دې طريقه مړۀ کړے شى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29746, 'Revelation 11:6', 'Revelation', 11, 6, '&nbsp;هغوئ سره به دا اختيار وى چې آسمان بند کړى چې د دوئ د پېشګويۍ په دور کښې به بيا باران ونۀ شى، او په اوبو د دوئ دا اختيار هم شته چې وينې ترې جوړې کړى او چې څومره غواړى دومره افتونه په زمکه راولى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29747, 'Revelation 11:7', 'Revelation', 11, 7, '&nbsp;کله چې دوئ خپله ګواهى پوره کړى نو د عالمِ ارواح نه به هغه بلا راوځى او دوئ سره به جنګ ونښلوى او کاميابه به شى او مړۀ به يې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29748, 'Revelation 11:8', 'Revelation', 11, 8, '&nbsp;او د هغوئ لاشونه به د لوئ ښار په کوڅو کښې پراتۀ وى، چې د مِثال په توګه ورته سدوم او مِصر وئيلے شى، په کوم ځائ کښې چې د دوئ مالِک هم په سولۍ شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29749, 'Revelation 11:9', 'Revelation', 11, 9, '&nbsp;تر درې نيمو ورځو پورې به خلق، د هرې قبيلې، د هرې ژبې او د هر قوم نه د دوئ لاشونو ته ګورى او د دوئ د لاشونو د ښخولو اجازت به ورنۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29750, 'Revelation 11:10', 'Revelation', 11, 10, '&nbsp;د زمکې ټول خلق به ورته په سترګو کښې خاندى او خوشحالۍ به کوى او يو بل ته به تحفې ورکوى ځکه چې دې دواړو نبيانو د زمکې ټول خلق عذابول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29751, 'Revelation 11:11', 'Revelation', 11, 11, '&nbsp;خو د درې نيمو ورځو نه پس خُدائ پاک په هغوئ کښې د ژوند ورکولو روح واچولو او هغوئ په خپلو پښو ودرېدل او چا چې دا وليدل، هغوئ ټول يرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29752, 'Revelation 11:12', 'Revelation', 11, 12, '&nbsp;بيا دوئ يو اوچت آواز د آسمان نه واورېدو چې هغوئ ته يې وئيل چې، ”دلته راشئ.“ او هغوئ په وريځو کښې آسمان ته وختل او دشمنانو هغوئ ته کتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29753, 'Revelation 11:13', 'Revelation', 11, 13, '&nbsp;هم په دغه وخت يوه سخته زلزله راغله، او د ښار لسمه حِصه راوغورزېدله. اووۀ زره کسان په دې زلزله کښې هلاک شول او نورو په يره کښې د آسمانى خُدائ پاک ثنا وئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29754, 'Revelation 11:14', 'Revelation', 11, 14, '&nbsp;دوېم افسوس تېر شو خو ګورئ درېم زر راتلونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29755, 'Revelation 11:15', 'Revelation', 11, 15, '&nbsp;بيا اوومې فرښتې خپل بيګل وغږولو او په آسمان کښې په زوره دا چغې شوې چې وئيل يې چې، ”د دُنيا د بادشاهۍ حق زمونږ د مالِک خُدائ او د هغۀ د مسيح دے او هغه به تل تر تله حکومت کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29756, 'Revelation 11:16', 'Revelation', 11, 16, '&nbsp;بيا هغه څليريشت مشران چې د خُدائ پاک د وړاندې په خپلو تختُونو ناست وُو، هغوئ پړمخې په سجده پرېوتل او د خُدائ پاک عبادت يې وکړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29757, 'Revelation 11:17', 'Revelation', 11, 17, '&nbsp;او دا يې وئيل چې، ”اے مالِکه قادر مطلق خُدايه، مونږ ستا شُکر کوُو، تۀ چې يې او چې وې، ځکه چې تا خپل لوئ طاقت استعمال کړو او بادشاهى دې شروع کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29758, 'Revelation 11:18', 'Revelation', 11, 18, '&nbsp;قومونه د قهر نه ډک شوى دى خو اوس ستا د قهر وخت راغلے دے، دا د مړو د عدالت کولو وخت دے. ستا د خادِمانو نبيانو د اجر وخت او ستا د مقدسينو او د هغه ټولو خلقو د لويو نه واخله تر وړو پورې د اجر ورکولو وخت راغلے دے، څوک چې ستا د نوم نه يرېدل. او دا اوس د هغوئ د تباه کېدلو وخت دے چا چې په زمکه کښې تباهى راوستله.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29759, 'Revelation 11:19', 'Revelation', 11, 19, '&nbsp;نو بيا په آسمان کښې د خُدائ پاک کور پرانستے شو او په هغه کور کښې د هغۀ د لوظ صندوق ښکاره شو، او بيا د برېښنا شُغلې، د تندر ګړزار، زلزله او د ږلۍ يو لوئ طوفان راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29760, 'Revelation 12:1', 'Revelation', 12, 1, '&nbsp;نو بيا په آسمان کښې يوه لويه نښه ښکاره شوه چې يوه ښځه وه چې نمر يې لکه د جامو اغوستے وو او سپوږمۍ د هغې د پښو لاندې وه او د هغې په سر د دولسو ستورو تاج وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29761, 'Revelation 12:2', 'Revelation', 12, 2, '&nbsp;هغه اُميدواره وه او د ماشوم د پېدا کېدو د درد په وجه يې چغې وهلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29762, 'Revelation 12:3', 'Revelation', 12, 3, '&nbsp;بيا يوه بله نښه په آسمان کښې ښکاره شوه چې يوه لويه سره اژدها وه چې اووۀ سرونه او لس ښکرونه يې وُو او په سرونو يې اووۀ واړه تاجونه وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29763, 'Revelation 12:4', 'Revelation', 12, 4, '&nbsp;هغې په خپله لکۍ درېمه حِصه ستورى د آسمان نه راښکل او په زمکه يې راغورزول. اژدها د هغې ښځې په وړاندې ودرېدله چې د ماشوم د پېدا کېدو په دردونو آخته وه د دې دپاره چې هر کله چې د هغې ښځې بچے وشى چې لواړ يې تېر کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29764, 'Revelation 12:5', 'Revelation', 12, 5, '&nbsp;د هغې ماشوم پېدا شو چې هلک وو کوم چې به په ټولو قومونو يعنې زورَور حکومت کوى. خو د هغې ماشوم سمدستى خُدائ پاک ته ونيولے شو او د هغۀ تخت ته راوستے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29765, 'Revelation 12:6', 'Revelation', 12, 6, '&nbsp;او ښځه بيابان ته وتښتېدله چرته چې د هغې د ساتنې دپاره خُدائ پاک ځائ تيار کړے وو چې هلته به د هغې د دولسو سوو شپېتو ورځو پورې حفاظت کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29766, 'Revelation 12:7', 'Revelation', 12, 7, '&nbsp;بيا په آسمان کښې جنګ ونښتو. ميکائيل او د هغې فرښتو د اژدها خلاف جنګ وکړو. او اژدها او د هغې فرښتو هم د هغوئ خلاف جنګ وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29767, 'Revelation 12:8', 'Revelation', 12, 8, '&nbsp;خو اژدها شکست وخوړو او د خپلو ملګرو سره د آسمان نه وشړل شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29768, 'Revelation 12:9', 'Revelation', 12, 9, '&nbsp;نو دا لويه اژدها لاندې راوغورزولے شوه، هغه زوړ مار چې شېطان يا اِبليس بللے شى چې ټوله دُنيا يې دوکه کړې ده، هغه د خپلو فرښتو سره لاندې زمکې ته راګزار کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29769, 'Revelation 12:10', 'Revelation', 12, 10, '&nbsp;بيا ما په آسمان کښې يو اوچت آواز واورېدو چې داسې يې وئيل چې، ”اوس خلاصون، قُدرت او زمونږ د خُدائ پاک بادشاهى او د هغۀ د مسيح اختيار راغلے دے، ځکه چې زمونږ په وروڼو اِلزام لګوونکى چې شپه او ورځ زمونږ د خُدائ پاک په مخکښې په هغوئ اِلزام لګوى، نو هغه د آسمان نه سر د لاندې راغورزولے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29770, 'Revelation 12:11', 'Revelation', 12, 11, '&nbsp;خو هغوئ په هغۀ د ګډُورى د وينې او د هغوئ د ګواهۍ کولو په وسيله کامياب شول، او هغوئ خپل ځان عزيز ونۀ ګڼلو تر دې چې مرګ ته تيار شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29771, 'Revelation 12:12', 'Revelation', 12, 12, '&nbsp;نو اے آسمانونو او په دې کښې اوسېدونکو خلقو، خوشحالى کوئ. خو اے زمکې او سمندره، په تاسو دې افسوس وى ځکه چې اِبليس ډېر په غصه تاسو ته ښکته راغلو ځکه چې هغه خبر دے چې د هغۀ وخت لنډ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29772, 'Revelation 12:13', 'Revelation', 12, 13, '&nbsp;نو چې کله اژدها خپل ځان په زمکه راغورزېدلے وليدو نو هغه، هغه ښځې پسې شوه چې زوئ يې شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29773, 'Revelation 12:14', 'Revelation', 12, 14, '&nbsp;خو ښځې ته د لوئ باز دوه وزرونه ورکړے شول نو چې هغه په بيابان کښې د اژدها نه خپل هغه ځائ ته والوځى چرته چې به تر درې نيم کالو پورې د هغې خيال وساتلے شى او محفوظه وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29774, 'Revelation 12:15', 'Revelation', 12, 15, '&nbsp;بيا اژدها د خپلې خولې نه د اوبو يو سېلاب وبهيولو چې هغه ښځه لاهو کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29775, 'Revelation 12:16', 'Revelation', 12, 16, '&nbsp;خو زمکې د ښځې مدد وکړو، او د اژدها د خولې هغه سېلاب يې تېر کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29776, 'Revelation 12:17', 'Revelation', 12, 17, '&nbsp;بيا اژدها هغه ښځې ته غصه شوه او د هغې د نور نسل سره د جنګ دپاره لاړه، دا هغه خلق دى چې د خُدائ پاک حُکمونه منى او د عيسىٰ په ګواهۍ ټينګ ولاړ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29777, 'Revelation 12:18', 'Revelation', 12, 18, '&nbsp;بيا اژدها د سمندر په غاړه ودرېده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29778, 'Revelation 13:1', 'Revelation', 13, 1, '&nbsp;بيا ما د سمندر نه يوه بلا په راوتو وليده. د هغې لس ښکرونه او اووۀ سرونه وُو، او د هغې په ښکرونو لس واړه تاجونه وُو او د دې په هر سر د کُفر جدا جدا نومونه وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29779, 'Revelation 13:2', 'Revelation', 13, 2, '&nbsp;او کومه بلا چې ما وليده، هغه د پړانګ په شان وه خو د هغې پښې د مېلو په شان وې او خولۀ يې د ازمرى په شان وه. او اژدها هغې ته خپل طاقت، بادشاهى او لوئ اختيار ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29780, 'Revelation 13:3', 'Revelation', 13, 3, '&nbsp;داسې ښکارېده چې د هغې يو سر د مرګى ګزار خوړلے وو خو د هغې ګزار ټيک شوے وو او ټوله دُنيا په هغې بلا پسې په حېرانتيا روانه وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29781, 'Revelation 13:4', 'Revelation', 13, 4, '&nbsp;هغوئ د اژدها عبادت وکړو ځکه چې هغې خپل اختيار بلا ته ورکړو، هغوئ د بلا عبادت هم وکړو او دا يې ووئيل چې، ”څوک د دې بلا په شان زورَوره ده، او څوک د دې خلاف جنګ کولے شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29782, 'Revelation 13:5', 'Revelation', 13, 5, '&nbsp;او بلا ته دا اختيار ورکړے شو چې غټې غټې او د کُفر خبرې وکړى، او تر دوو څلوېښتو مياشتو پورې د حکومت کولو اجازت ورکړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29783, 'Revelation 13:6', 'Revelation', 13, 6, '&nbsp;هغې په خپله خوله د خُدائ پاک خلاف د کُفر خبرې وکړې او د خُدائ نوم او د هغۀ د استوګنې ځائ او آسمانى مخلوق پسې يې کُفر وغرولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29784, 'Revelation 13:7', 'Revelation', 13, 7, '&nbsp;هغې ته دا اجازت هم ورکړے شو چې د مقدسينو سره جنګ وکړى او پرې کاميابه شى، او په ټولو خيلونو او خلقو، ژبو او قومونو اختيار ورکړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29785, 'Revelation 13:8', 'Revelation', 13, 8, '&nbsp;او د زمکې ټول اوسېدونکى به د هغې عبادت وکړى هغوئ ټول د چا نومونه چې د هغه حلال شوى ګډُورى د ژوندون په کِتاب کښې د ازل نه ليکلے شوى نۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29786, 'Revelation 13:9', 'Revelation', 13, 9, '&nbsp;د چا چې غوږونه وى هغه دې واورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29787, 'Revelation 13:10', 'Revelation', 13, 10, '&nbsp;کۀ چا ته قېدېدل وى هغه به قېد شى، کۀ څوک په تُوره قتل کېدل وى نو هغه به په تُوره قتل شى. په دې مقدسينو ته زغم او ايمان په کار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29788, 'Revelation 13:11', 'Revelation', 13, 11, '&nbsp;بيا ما يو بله بلا وليده چې د زمکې نه راووتله، د هغې د ګډُورى په شان دوه ښکرونه وُو او دې د اژدها په شان خبرې کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29789, 'Revelation 13:12', 'Revelation', 13, 12, '&nbsp;هغه د اولنۍ بلا ټول اختيار د هغې په ځائ استعمالوى، زمکه او د دې اوسېدونکى دې خبرې ته مجبوروى چې د اولنۍ بلا عبادت وکړى چې د چا د مرګى زخم ټيک شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29790, 'Revelation 13:13', 'Revelation', 13, 13, '&nbsp;هغې غټې معجزې کولې تر دې چې د خلقو په وړاندې يې د آسمان نه زمکې ته اور نازل کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29791, 'Revelation 13:14', 'Revelation', 13, 14, '&nbsp;او هغې له دا اختيار ورکړے شو چې د هغې اولنۍ بلا په ځائ معجزې وکړى او د دُنيا اوسېدونکى دوکه کړى او ورته يې حُکم وکړو چې د هغې اولنۍ په شان يو بُت جوړ کړئ چې د تُورې ګزار يې خوړلے وو خو بيا هم لا ژوندې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29792, 'Revelation 13:15', 'Revelation', 13, 15, '&nbsp;او ورته دا اختيار ورکړے شو چې د بلا په بُت کښې ساه واچوى نو چې د خبرو طاقت هم ورکړى او هغوئ څوک چې ورته سجده نۀ کوى، مړۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29793, 'Revelation 13:16', 'Revelation', 13, 16, '&nbsp;هغۀ دا هم وکړل چې واړۀ او لوئ، مالداره او غريب، آزاد او غلامان ټول دې په ښى لاس يا په تندى يوه نښه ولګوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29794, 'Revelation 13:17', 'Revelation', 13, 17, '&nbsp;او چا ته هم د څۀ اخستلو يا خرڅولو اجازت تر هغې نۀ وو ترڅو پورې به چې د دې بلا نښه، يا د هغې د نامې شمېره پرې نۀ وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29795, 'Revelation 13:18', 'Revelation', 13, 18, '&nbsp;نو په دې وخت کښې د دې حکمت ضرورت دے. څوک چې پوهه وى هغه دې د دې بلا د نامې د شمېرې حساب وکړى، دا شمېره د يو سړى ده او د هغۀ د شمېرې حساب شپږ سوه شپږ شپېتۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29796, 'Revelation 14:1', 'Revelation', 14, 1, '&nbsp;بيا ما وليدل چې د صيون په غرۀ باندې ګډُورے ولاړ وو چې ورسره يو لاک څلور څلوېښت زره کسان وُو چې په تندو يې د هغۀ نوم او د هغۀ د پلار نوم ليکلے شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29797, 'Revelation 14:2', 'Revelation', 14, 2, '&nbsp;او ما د آسمان نه داسې آواز واورېدو لکه د سيند د اوبو غړمبار او يا لکه د تندر د ګړزار، او دا د هغه آوازونو په شان وو لکه چې ستار غږوونکى خپل ستارونه غږوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29798, 'Revelation 14:3', 'Revelation', 14, 3, '&nbsp;او هغوئ د تخت او د څلورو جاندارو او مشرانو په وړاندې يو نوے حمد وئيلو، او دا حمد بې د هغه يو لاک څلور څلوېښت زرو کسانو نه چې د زمکې نه په بيعه اخستے شوى وُو، او د دوئ نه بغېر بل هيچا نۀ شو زده کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29799, 'Revelation 14:4', 'Revelation', 14, 4, '&nbsp;دا هغه خلق دى چا چې خپل ځانونه د ښځو سره د يو ځائ کېدو نه ساتلى دى، او ګډُورى پسې روان دى چرته چې هم ګډُورے ځى. دوئ د خُدائ پاک او د ګډُورى دپاره د بنى آدمو نه د اولنۍ مېوې په طور په بيعه اخستے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29800, 'Revelation 14:5', 'Revelation', 14, 5, '&nbsp;د هغوئ ژبو کله دروغ نۀ وو وئيلى او هغوئ بې‌داغه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');